//
// Usage:
//   cargo run --release --example validate -- [filter]
//
// Validation runner of the tutor examples (the Rust counterpart of
// julia/tutor/validate.jl): every example program runs with its quick
// configuration into a temporary directory and the observables are
// compared pointwise with the NESSi reference data in data/tutor
// (generated by .nessi/kbref/generate.sh). Prints one line per check
// and exits nonzero on the first failure.
//
// The examples are located next to this binary (target/<profile>/examples).
//

use std::path::PathBuf;
use std::process::Command;

fn workspace_root() -> PathBuf {
    // walk up from the example binary until the workspace markers appear
    let exe = std::env::current_exe().expect("current exe");
    let mut dir = exe.parent().expect("exe dir").to_path_buf();
    loop {
        if dir.join("Cargo.toml").is_file() && dir.join("data").join("tutor").is_dir() {
            return dir;
        }
        dir = match dir.parent() {
            Some(p) => p.to_path_buf(),
            None => panic!("workspace root with data/tutor not found"),
        };
    }
}

fn example_dir() -> PathBuf {
    let exe = std::env::current_exe().expect("current exe");
    exe.parent().expect("exe dir").to_path_buf()
}

struct Check {
    name: String,
    passed: bool,
    detail: String,
}

impl Check {
    fn ok(name: &str, detail: &str) -> Self {
        Check {
            name: name.to_string(),
            passed: true,
            detail: detail.to_string(),
        }
    }
    fn fail(name: &str, detail: &str) -> Self {
        Check {
            name: name.to_string(),
            passed: false,
            detail: detail.to_string(),
        }
    }
}

/// Read the kbref-style reference rows `(component, i, value)`.
fn ref_rows(path: &PathBuf) -> Vec<(String, i64, f64)> {
    let text = std::fs::read_to_string(path).expect("reference file");
    text.lines()
        .filter(|l| !l.starts_with('#') && !l.trim().is_empty())
        .map(|l| {
            let p: Vec<&str> = l.split_whitespace().collect();
            (p[0].to_string(), p[1].parse().unwrap(), p[5].parse().unwrap())
        })
        .collect()
}

/// Read a whitespace-separated numeric table (skipping `#` lines).
fn table_rows(path: &PathBuf) -> Vec<Vec<f64>> {
    let text = std::fs::read_to_string(path).expect("output file");
    text.lines()
        .filter(|l| !l.starts_with('#') && !l.trim().is_empty())
        .map(|l| {
            l.split_whitespace()
                .map(|x| x.parse().unwrap())
                .collect()
        })
        .collect()
}

/// Compare reference rows against a keyed output table with the given
/// column map; returns (checked, failed, worst).
fn compare_rows(
    refs: &[(String, i64, f64)],
    table: &[Vec<f64>],
    key_col: usize,
    cols: fn(&str) -> Option<usize>,
    h: f64,
    tol: f64,
) -> (usize, usize, f64) {
    let mut keyed = std::collections::HashMap::new();
    for r in table {
        keyed.insert((r[key_col] * 1e8).round() as i64, r.clone());
    }
    let (mut n, mut bad, mut worst) = (0usize, 0usize, 0f64);
    for (comp, i, rv) in refs {
        let Some(col) = cols(&comp.replace(".re", "")) else {
            continue;
        };
        if *i < 0 {
            // the Matsubara branch rows live in the state, not the tables
            continue;
        }
        let Some(row) = keyed.get(&(((*i as f64) * h * 1e8).round() as i64)) else {
            bad += 1;
            continue;
        };
        n += 1;
        let e = (row[col] - rv).abs();
        worst = worst.max(e);
        if e > tol + tol * rv.abs() {
            bad += 1;
        }
    }
    (n, bad, worst)
}


/// Read the `h = ...` value of a tutor TOML (the first match).
fn toml_h(root: &PathBuf, toml_rel: &str) -> f64 {
    let text = std::fs::read_to_string(root.join(toml_rel)).expect("toml");
    for l in text.lines() {
        let t = l.trim();
        if t.starts_with("h =") {
            return t.split('=').nth(1).unwrap().trim().parse().unwrap();
        }
    }
    panic!("no h in {toml_rel}");
}

/// Run one example binary with a config redirected into `outdir`.
fn run_example(name: &str, toml_rel: &str, outdir: &std::path::Path, extra: &[&str]) -> Result<(), String> {
    let root = workspace_root();
    let src = root.join(toml_rel);
    let text = std::fs::read_to_string(&src).map_err(|e| e.to_string())?;
    // redirect dir = "." (and any relative dir) into the temp directory
    let redirected = text.replace("dir = \".\"", &format!("dir = {:?}", outdir.display().to_string()));
    let cfg = outdir.join("case.toml");
    std::fs::write(&cfg, redirected).map_err(|e| e.to_string())?;
    let exe = example_dir().join(name);
    let out = Command::new(&exe)
        .arg(&cfg)
        .args(extra)
        .output()
        .map_err(|e| format!("{name}: {e}"))?;
    if !out.status.success() {
        return Err(format!(
            "{name} failed: {}",
            String::from_utf8_lossy(&out.stderr)
        ));
    }
    Ok(())
}

fn main() {
    let root = workspace_root();
    let data = root.join("data/tutor");
    let tmp = std::env::temp_dir().join(format!("kb-r9-validate-{}", std::process::id()));
    std::fs::create_dir_all(&tmp).expect("temp dir");
    let mut checks: Vec<Check> = Vec::new();

    // ---- hubbard_chain (2B / GW / TPP) ---------------------------------
    for approx in ["2b", "gw", "tpp"] {
        let dir = tmp.join(format!("hc_{approx}"));
        std::fs::create_dir_all(&dir).unwrap();
        match run_example(
            &format!("hubbard_chain_{approx}"),
            "julia/tutor/hubbard_chain/hubbard_chain.toml",
            &dir,
            &["--profile", "quick"],
        ) {
            Ok(()) => {
                let hh = toml_h(&root, "julia/tutor/hubbard_chain/hubbard_chain.toml");
                let refs = ref_rows(&data.join(format!("hubbard_{approx}_quick.dat")));
                let occ = table_rows(&dir.join(format!("hubbardchain_{approx}_occupation.dat")));
                let en = table_rows(&dir.join(format!("hubbardchain_{approx}_energy.dat")));
                let lookup = |t: &[Vec<f64>]| {
                    let mut m = std::collections::HashMap::new();
                    for r in t {
                        m.insert((r[0] * 1e8).round() as i64, r.clone());
                    }
                    m
                };
                let (om, em) = (lookup(&occ), lookup(&en));
                let (mut n, mut bad, mut worst) = (0, 0, 0f64);
                for (comp, i, rv) in &refs {
                    let m = if comp == "n1" { &om } else { &em };
                    let col = if comp == "n1" {
                        1
                    } else {
                        1 + ["Ekin", "Epot", "Etot"].iter().position(|c| c == comp).unwrap()
                    };
                    let key = ((*i as f64) * hh * 1e8).round() as i64;
                    let Some(row) = m.get(&key) else { bad += 1; continue };
                    n += 1;
                    let e = (row[col] - rv).abs();
                    worst = worst.max(e);
                    bad += (e > 1e-10 + 1e-10 * rv.abs()) as usize;
                }
                checks.push(if bad == 0 {
                    Check::ok(
                        &format!("hubbard_chain_{approx}"),
                        &format!("{n} rows, worst {worst:.2e}"),
                    )
                } else {
                    Check::fail(
                        &format!("hubbard_chain_{approx}"),
                        &format!("{bad}/{n} rows fail, worst {worst:.2e}"),
                    )
                });
            }
            Err(e) => checks.push(Check::fail(&format!("hubbard_chain_{approx}"), &e)),
        }
    }

    // ---- fkm_bethe ------------------------------------------------------
    {
        let dir = tmp.join("fkm");
        std::fs::create_dir_all(&dir).unwrap();
        match run_example("fkm_bethe", "julia/tutor/fkm_bethe/fkm_bethe.toml", &dir, &["--profile", "quick"]) {
            Ok(()) => {
                let hf = toml_h(&root, "julia/tutor/fkm_bethe/fkm_bethe.toml");
                let refs = ref_rows(&data.join("fkm_bethe_quench_quick.dat"));
                let tab = table_rows(&dir.join("fkm_bethe_quench_density.dat"));
                let cols = |c: &str| match c {
                    "den0" => Some(1),
                    "den1" => Some(2),
                    "total" => Some(3),
                    _ => None,
                };
                let (n, bad, worst) = compare_rows(&refs, &tab, 0, cols, hf, 1e-10);
                let c = if bad == 0 {
                    Check::ok("fkm_bethe", &format!("{n} rows (real time), worst {worst:.2e}"))
                } else {
                    Check::fail("fkm_bethe", &format!("{bad}/{n} rows fail, worst {worst:.2e}"))
                };
                checks.push(c);
            }
            Err(e) => checks.push(Check::fail("fkm_bethe", &e)),
        }
    }

    // ---- holstein_bethe (4 variants) -------------------------------------
    for (approx, refn, nambu) in [
        ("migdal", "holstein_bethe_migdal", false),
        ("umig", "holstein_bethe_umig", false),
        ("nambu_migdal", "holstein_nambu_migdal", true),
        ("nambu_umig", "holstein_nambu_umig", true),
    ] {
        let dir = tmp.join(format!("hb_{approx}"));
        std::fs::create_dir_all(&dir).unwrap();
        let toml = format!("julia/tutor/holstein_bethe/holstein_bethe_{approx}.toml");
        match run_example(&format!("holstein_bethe_{approx}"), &toml, &dir, &["--profile", "quick"]) {
            Ok(()) => {
                let hb_h = toml_h(&root, &toml);
                let tab = table_rows(&dir.join(format!("holstein_bethe_{approx}_obs.dat")));
                if nambu {
                    // the reference carries the rho(a,b) orbital indices
                    let text = std::fs::read_to_string(data.join(format!("{refn}_quick.dat"))).unwrap();
                    let mut keyed = std::collections::HashMap::new();
                    for r in &tab {
                        keyed.insert((r[0] * 1e8).round() as i64, r.clone());
                    }
                    let (mut n, mut bad, mut worst) = (0usize, 0usize, 0f64);
                    for l in text.lines().filter(|l| !l.starts_with('#') && !l.trim().is_empty()) {
                        let p: Vec<&str> = l.split_whitespace().collect();
                        let i: f64 = p[1].parse().unwrap();
                        // the non-rho rows carry -1 placeholders
                        let (a, b): (usize, usize) = (
                            p[3].parse::<i64>().unwrap().max(0) as usize,
                            p[4].parse::<i64>().unwrap().max(0) as usize,
                        );
                        let rv: f64 = p[5].parse().unwrap();
                        let col = match p[0] {
                            "rho" => Some(1 + 2 * (2 * a + b)),
                            "XX" => Some(9),
                            "Ekin" => Some(10),
                            "Enx_MF" => Some(11),
                            "Enx_corr" => Some(12),
                            "Eph" => Some(13),
                            "Etot" => Some(14),
                            _ => None,
                        };
                        let Some(col) = col else { continue };
                        let Some(row) = keyed.get(&((i * hb_h * 1e8).round() as i64)) else {
                            bad += 1;
                            continue;
                        };
                        n += 1;
                        let e = (row[col] - rv).abs();
                        worst = worst.max(e);
                        bad += (e > 1e-10 + 1e-10 * rv.abs()) as usize;
                    }
                    let c = if bad == 0 {
                        Check::ok(&format!("holstein_bethe_{approx}"), &format!("{n} rows, worst {worst:.2e}"))
                    } else {
                        Check::fail(&format!("holstein_bethe_{approx}"), &format!("{bad}/{n} rows fail, worst {worst:.2e}"))
                    };
                    checks.push(c);
                    continue;
                }
                let refs = ref_rows(&data.join(format!("{refn}_quick.dat")));
                let cols_n: fn(&str) -> Option<usize> = |c: &str| match c {
                    "rho" => Some(1),
                    "XX" => Some(9),
                    "Ekin" => Some(10),
                    "Enx_MF" => Some(11),
                    "Enx_corr" => Some(12),
                    "Eph" => Some(13),
                    "Etot" => Some(14),
                    _ => None,
                };
                let cols: fn(&str) -> Option<usize> = |c: &str| match c {
                    "rho" => Some(1),
                    "Xph" => Some(3),
                    "Pph" => Some(4),
                    "XX" => Some(5),
                    "Ekin" => Some(6),
                    "Exn_MF" => Some(7),
                    "Exn_corr" => Some(8),
                    "Eph_cl" => Some(9),
                    "Eph_corr" => Some(10),
                    "Etot" => Some(11),
                    _ => None,
                };
                let (f, w) = if nambu {
                    (hb_h, cols_n)
                } else {
                    (hb_h, cols)
                };
                let (n, bad, worst) = compare_rows(&refs, &tab, 0, w, f, 1e-10);
                let c = if bad == 0 {
                    Check::ok(&format!("holstein_bethe_{approx}"), &format!("{n} rows, worst {worst:.2e}"))
                } else {
                    Check::fail(&format!("holstein_bethe_{approx}"), &format!("{bad}/{n} rows fail, worst {worst:.2e}"))
                };
                checks.push(c);
            }
            Err(e) => checks.push(Check::fail(&format!("holstein_bethe_{approx}"), &e)),
        }
    }

    // ---- holstein_impurity (2 variants) ----------------------------------
    for approx in ["migdal", "umig"] {
        let dir = tmp.join(format!("hi_{approx}"));
        std::fs::create_dir_all(&dir).unwrap();
        let toml = format!("julia/tutor/holstein_impurity/holstein_impurity_singlebath_{approx}.toml");
        match run_example(&format!("holstein_impurity_singlebath_{approx}"), &toml, &dir, &["--profile", "quick"]) {
            Ok(()) => {
                let refs = ref_rows(&data.join(format!("holstein_impurity_{approx}_quick.dat")));
                let tab = table_rows(&dir.join(format!("holstein_impurity_singlebath_{approx}_obs.dat")));
                let cols: fn(&str) -> Option<usize> = |c: &str| match c {
                    "rho00" => Some(1),
                    "rho11" => Some(3),
                    "Xph" => Some(5),
                    "Pph" => Some(6),
                    "XX" => Some(7),
                    "Ekin" => Some(8),
                    "Exn_MF" => Some(9),
                    "Exn_corr" => Some(10),
                    "Eph_cl" => Some(11),
                    "Eph_corr" => Some(12),
                    "Etot" => Some(13),
                    _ => None,
                };
                let h = toml_h(&root, &toml);
                let (n, bad, worst) = compare_rows(&refs, &tab, 0, cols, h, 1e-10);
                let c = if bad == 0 {
                    Check::ok(&format!("holstein_impurity_{approx}"), &format!("{n} rows, worst {worst:.2e}"))
                } else {
                    Check::fail(&format!("holstein_impurity_{approx}"), &format!("{bad}/{n} rows fail, worst {worst:.2e}"))
                };
                checks.push(c);
            }
            Err(e) => checks.push(Check::fail(&format!("holstein_impurity_{approx}"), &e)),
        }
    }

    // ---- ness2 (density / Eint from the observables file) ----------------
    {
        let dir = tmp.join("ness2");
        std::fs::create_dir_all(&dir).unwrap();
        match run_example("hubbard_bethe_ness2", "julia/tutor/hubbard_bethe/hubbard_bethe_ness2.toml", &dir, &[]) {
            Ok(()) => {
                let obs = std::fs::read_to_string(dir.join("bethe_ness2_observables.dat")).unwrap();
                let vals: Vec<f64> = obs
                    .lines()
                    .filter(|l| !l.starts_with('#') && !l.trim().is_empty())
                    .next()
                    .unwrap()
                    .split_whitespace()
                    .map(|x| x.parse().unwrap())
                    .collect();
                let (dens, eint) = (vals[0], vals[1]);
                // the steady state of the Julia blueprint (8 digits)
                let ok = (dens - 0.99993334).abs() < 5e-8 && (eint - (-0.1717343)).abs() < 5e-7;
                let c = if ok {
                    Check::ok("hubbard_bethe_ness2", &format!("density {dens:.8}, Eint {eint:.8}"))
                } else {
                    Check::fail("hubbard_bethe_ness2", &format!("density {dens:.8}, Eint {eint:.8}"))
                };
                checks.push(c);
            }
            Err(e) => checks.push(Check::fail("hubbard_bethe_ness2", &e)),
        }
    }

    // ---- trunc / ness2_trunc: row-structural checks -----------------------
    for (name, toml, out, nrows) in [
        ("hubbard_bethe_trunc", "julia/tutor/hubbard_bethe/hubbard_bethe_trunc.toml", "bethe_trunc_density.dat", 42usize),
        (
            "hubbard_bethe_ness2_trunc",
            "julia/tutor/hubbard_bethe/hubbard_bethe_ness2_trunc.toml",
            "bethe_ness2_trunc_trunc_density.dat",
            11,
        ),
    ] {
        let dir = tmp.join(name);
        std::fs::create_dir_all(&dir).unwrap();
        match run_example(name, toml, &dir, &[]) {
            Ok(()) => {
                let tab = table_rows(&dir.join(out));
                let finite = tab.iter().all(|r| r.iter().all(|x| x.is_finite()));
                let ok = tab.len() == nrows && finite;
                let c = if ok {
                    Check::ok(name, &format!("{} rows, all finite", tab.len()))
                } else {
                    Check::fail(name, &format!("{} rows, finite={}", tab.len(), finite))
                };
                checks.push(c);
            }
            Err(e) => checks.push(Check::fail(name, &e)),
        }
    }

    // ---- gw (reference p8_gw.dat) ----------------------------------------
    {
        let dir = tmp.join("gw");
        std::fs::create_dir_all(&dir).unwrap();
        match run_example("gw", "julia/tutor/gw/gw.toml", &dir, &[]) {
            Ok(()) => {
                let tab = table_rows(&dir.join("gw_observables.dat"));
                // the columns: tstp t E A Ekin Eint Etot density current
                // the Julia run values (bit-identical output verified in W7)
                let want_last = [-0.5921373673f64, 0.2303739311, 0.0000006866];
                let last = tab.last().unwrap();
                let ok = (last[4] - want_last[0]).abs() < 1e-9
                    && (last[5] - want_last[1]).abs() < 1e-9
                    && (last[8] - want_last[2]).abs() < 1e-9;
                let c = if ok {
                    Check::ok("gw", &format!("Ekin {:.10}, Eint {:.10}, current {:.10}", last[4], last[5], last[8]))
                } else {
                    Check::fail("gw", &format!("Ekin {:.10}, Eint {:.10}, current {:.10}", last[4], last[5], last[8]))
                };
                checks.push(c);
            }
            Err(e) => checks.push(Check::fail("gw", &e)),
        }
    }

    // ---- summary -----------------------------------------------------------
    let mut failed = 0;
    println!();
    for c in &checks {
        let mark = if c.passed { "PASS" } else { "FAIL" };
        if !c.passed {
            failed += 1;
        }
        println!("[{mark}] {:<28} {}", c.name, c.detail);
    }
    let _ = std::fs::remove_dir_all(&tmp);
    println!();
    if failed == 0 {
        println!("validate: {} checks passed", checks.len());
    } else {
        println!("validate: {failed}/{} checks FAILED", checks.len());
        std::process::exit(1);
    }
}
